script:
if doc.get("product_delivery"):
    frappe.db.set_value("Product Delivery", doc.product_delivery, {
        "transfer_status": "Transferred",
        "stock_entry": doc.name
    })

if doc.get("product_delivery"):
    frappe.db.set_value("Product Delivery", doc.product_delivery, {
        "transfer_status": "Pending",
        "stock_entry": None
    })

if doc.get("installation"):
    if doc.purpose == "Material Issue":
        frappe.db.set_value("Installation", doc.installation, {
            "consumption_stock_entry": doc.name,
            "material_status": "Consumption Posted"
        })
    elif doc.purpose == "Material Transfer":
        frappe.db.set_value("Installation", doc.installation, {
            "return_stock_entry": doc.name,
            "material_status": "Closed"
        })

if doc.get("installation"):
    if doc.purpose == "Material Issue":
        frappe.db.set_value("Installation", doc.installation, {
            "consumption_stock_entry": None,
            "material_status": "Pending"
        })
    elif doc.purpose == "Material Transfer":
        frappe.db.set_value("Installation", doc.installation, {
            "return_stock_entry": None,
            "material_status": "Consumption Posted"
        })

rows = doc.get("commissioning_checklist") or []

required = [r for r in rows if r.is_required]
pending = [r for r in required if r.status not in ("OK", "Not Applicable")]
failed = [r for r in rows if r.status == "Not OK"]
cleared = len(required) - len(pending)

summary = str(cleared) + " of " + str(len(required)) + " required checks cleared"
if failed:
    summary = summary + "  •  " + str(len(failed)) + " marked Not OK"
doc.checks_summary = summary

if doc.status_of_project_commission == "Commissioned":
    problems = []

    if not rows:
        problems.append("The commissioning checklist is empty.")

    if pending:
        names = ", ".join([r.check_item for r in pending[:5]])
        extra = " and " + str(len(pending) - 5) + " more" if len(pending) > 5 else ""
        problems.append("These required checks are not cleared: " + names + extra)

    if failed:
        names = ", ".join([r.check_item for r in failed[:5]])
        problems.append("These checks are marked Not OK: " + names)

    if not doc.commissioning_certificate:
        problems.append("Commissioning Certificate is not attached.")

    if not doc.final_handover_document:
        problems.append("Final Handover Document is not attached.")

    if not doc.customer_acceptance:
        problems.append("Customer Acceptance has not been ticked.")

    if problems:
        frappe.throw("Cannot mark this project as Commissioned yet:<br><br>• " + "<br>• ".join(problems))

# Stamps the consumed date, derives the warranty and AMC expiry dates from
# their period and unit, and sets both statuses. Runs server side so it also
# applies when a stock transaction changes the serial rather than a user
# editing the form.

# Once set, the consumed date is never cleared - the warranty start must
# survive any later status change.
if doc.status == "Consumed" and not doc.custom_consumed_date:
    doc.custom_consumed_date = frappe.utils.nowdate()

today = frappe.utils.getdate(frappe.utils.nowdate())

# ---- warranty ----
w_start = doc.custom_consumed_date
w_qty = frappe.utils.cint(doc.custom_warranty_period)
w_unit = doc.custom_warranty_period_unit or "Years"

if w_start and w_qty > 0:
    d = frappe.utils.getdate(w_start)
    if w_unit == "Days":
        doc.warranty_expiry_date = frappe.utils.add_days(d, w_qty)
    elif w_unit == "Months":
        doc.warranty_expiry_date = frappe.utils.add_months(d, w_qty)
    else:
        doc.warranty_expiry_date = frappe.utils.add_months(d, w_qty * 12)
elif not w_start:
    doc.warranty_expiry_date = None

if not w_start or not doc.warranty_expiry_date:
    doc.custom_warranty_status = "Not Started"
elif frappe.utils.getdate(doc.warranty_expiry_date) >= today:
    doc.custom_warranty_status = "Ongoing"
else:
    doc.custom_warranty_status = "Expired"

# ---- amc ----
# AMC start is entered by hand, since it usually begins when the warranty ends
# rather than on the consumed date.
a_start = doc.custom_amc_start_date
a_qty = frappe.utils.cint(doc.custom_amc_period)
a_unit = doc.custom_amc_period_unit or "Years"

if a_start and a_qty > 0:
    d = frappe.utils.getdate(a_start)
    if a_unit == "Days":
        doc.amc_expiry_date = frappe.utils.add_days(d, a_qty)
    elif a_unit == "Months":
        doc.amc_expiry_date = frappe.utils.add_months(d, a_qty)
    else:
        doc.amc_expiry_date = frappe.utils.add_months(d, a_qty * 12)
elif not a_start:
    doc.amc_expiry_date = None

if not a_start or not doc.amc_expiry_date:
    doc.custom_amc_status = "Not Started"
elif frappe.utils.getdate(doc.amc_expiry_date) >= today:
    doc.custom_amc_status = "Ongoing"
else:
    doc.custom_amc_status = "Expired"

# Keep ERPNext's own Maintenance Status consistent with the two above.
if doc.custom_amc_status == "Ongoing":
    doc.maintenance_status = "Under AMC"
elif doc.custom_warranty_status == "Ongoing":
    doc.maintenance_status = "Under Warranty"
elif doc.custom_amc_status == "Expired":
    doc.maintenance_status = "Out of AMC"
elif doc.custom_warranty_status == "Expired":
    doc.maintenance_status = "Out of Warranty"

# Lead: GPS coordinates -> Place, and Full Address.
#
# Place = nearest landmark  (e.g. "Pathiripala Bus Stop")
#      or nearest named road (e.g. "Peradikkunnu Road, Old Lakkidi")
#      or nearest locality   (e.g. "Ottapalam")
#
# DATA SOURCE
#   GOOGLE_API_KEY empty  -> OpenStreetMap (free)
#   GOOGLE_API_KEY filled -> Google Maps (falls back to OpenStreetMap if Google fails)
# Full Address always comes from OpenStreetMap.
# Never raises: on any error an empty result is returned.

# ---------------- SETTINGS (edit here) ----------------
GOOGLE_API_KEY = ""
GOOGLE_LANDMARKS = True
KNOWN_PLACES = []              # optional manual overrides: ["Name", lat, lon, radius_m]
LANDMARK_RADIUS_M = 150
ROAD_RADIUS_M = 150
LOCALITY_RADIUS_M = 5000
SHOW_LOCALITY_WITH_LANDMARK = True
MAJOR_BONUS_M = 40
MAJOR_TYPES = ["bus_stop", "bus_station", "station", "halt", "platform", "stop_position",
               "school", "college", "university", "hospital", "clinic", "place_of_worship",
               "fuel", "bank", "police", "post_office", "townhall", "marketplace", "cinema",
               "theatre", "supermarket", "mall"]
PLACE_TYPES = ["city", "town", "village", "suburb", "hamlet", "neighbourhood", "quarter", "locality"]
UA = {"User-Agent": "HipersignERP-Lead/1.0 (hipersignerp.cloud)"}
# ------------------------------------------------------

def dist_m(a_lat, a_lon, b_lat, b_lon):
    r = a_lat * 0.017453293
    c = 1 - (r * r) / 2 + (r ** 4) / 24
    dy = (b_lat - a_lat) * 111320.0
    dx = (b_lon - a_lon) * 111320.0 * c
    return (dx * dx + dy * dy) ** 0.5

def seg_dist_m(p_lat, p_lon, a_lat, a_lon, b_lat, b_lon):
    r = p_lat * 0.017453293
    c = 1 - (r * r) / 2 + (r ** 4) / 24
    ax = (a_lon - p_lon) * 111320.0 * c
    ay = (a_lat - p_lat) * 111320.0
    bx = (b_lon - p_lon) * 111320.0 * c
    by = (b_lat - p_lat) * 111320.0
    dx = bx - ax
    dy = by - ay
    L = dx * dx + dy * dy
    t = 0.0
    if L > 0:
        t = -(ax * dx + ay * dy) / L
        if t < 0:
            t = 0.0
        if t > 1:
            t = 1.0
    x = ax + t * dx
    y = ay + t * dy
    return (x * x + y * y) ** 0.5

def pretty(n):
    n = (n or "").strip()
    if n and n == n.lower():
        n = n.title()
    return n

result = {"place": "", "address": "", "landmark": "", "road": "", "locality": "", "city": "", "state": "", "source": ""}
lat = None
lon = None
try:
    lat = float(frappe.form_dict.get("latitude"))
    lon = float(frappe.form_dict.get("longitude"))
except Exception:
    lat = None

valid = False
if lat is not None and lon is not None:
    valid = (-90 <= lat <= 90) and (-180 <= lon <= 180) and not (abs(lat) < 0.0000001 and abs(lon) < 0.0000001)

if valid:
    landmark = None
    locality = None
    road = None
    source = "openstreetmap"

    kp_d = None
    for kp in KNOWN_PLACES:
        d = dist_m(lat, lon, kp[1], kp[2])
        if d <= kp[3] and (kp_d is None or d < kp_d):
            locality = kp[0]
            kp_d = d

    used_google = False
    if GOOGLE_API_KEY:
        try:
            g = frappe.make_get_request(
                "https://maps.googleapis.com/maps/api/geocode/json",
                params={"latlng": str(lat) + "," + str(lon), "key": GOOGLE_API_KEY, "language": "en"},
            ) or {}
            if g.get("status") == "OK":
                used_google = True
                source = "google"
                gres = g.get("results") or []
                if not locality:
                    for t in ["neighborhood", "sublocality_level_3", "sublocality_level_2", "sublocality_level_1", "sublocality", "locality", "administrative_area_level_3"]:
                        if locality:
                            break
                        for res in gres:
                            if locality:
                                break
                            for comp in (res.get("address_components") or []):
                                if t in (comp.get("types") or []):
                                    locality = comp.get("long_name")
                                    break
            else:
                frappe.log_error("Google geocoding status: " + str(g.get("status")) + " " + str(g.get("error_message") or ""))
        except Exception:
            frappe.log_error("Google geocoding failed")

        if used_google and GOOGLE_LANDMARKS:
            try:
                p = frappe.make_post_request(
                    "https://places.googleapis.com/v1/places:searchNearby",
                    json={
                        "maxResultCount": 5,
                        "rankPreference": "DISTANCE",
                        "languageCode": "en",
                        "locationRestriction": {"circle": {"center": {"latitude": lat, "longitude": lon}, "radius": float(LANDMARK_RADIUS_M)}},
                    },
                    headers={
                        "Content-Type": "application/json",
                        "X-Goog-Api-Key": GOOGLE_API_KEY,
                        "X-Goog-FieldMask": "places.displayName,places.location",
                    },
                ) or {}
                for pl in (p.get("places") or []):
                    nm = (pl.get("displayName") or {}).get("text")
                    if nm:
                        landmark = nm
                        break
            except Exception:
                frappe.log_error("Google nearby landmark lookup failed")

    if not used_google or not locality:
        try:
            ll = str(lat) + "," + str(lon)
            a = "(around:" + str(LANDMARK_RADIUS_M) + "," + ll + ")"
            q = "[out:json][timeout:12];("
            for sel in ["[highway=bus_stop]", "[public_transport]", "[amenity]", "[shop]", "[railway~\"^(station|halt)$\"]",
                        "[tourism]", "[office]", "[leisure]", "[historic]", "[healthcare]"]:
                q = q + "nwr" + a + sel + "[name];"
            q = q + "node(around:" + str(LOCALITY_RADIUS_M) + "," + ll + ")[place~\"^(city|town|village|suburb|hamlet|neighbourhood|quarter|locality)$\"][name];"
            q = q + ");out center 300;"
            q = q + "way(around:" + str(ROAD_RADIUS_M) + "," + ll + ")[highway~\"^(trunk|primary|secondary|tertiary|unclassified|residential|living_street|service|road|track)$\"][name];out geom 30;"

            data = frappe.make_get_request("https://overpass-api.de/api/interpreter", params={"data": q}, headers=UA) or {}
            o_landmark = None
            lm_score = None
            o_locality = None
            loc_d = None
            o_road = None
            road_d = None
            for el in (data.get("elements") or []):
                tags = el.get("tags") or {}
                name = tags.get("name:en") or tags.get("int_name") or tags.get("name")
                if not name:
                    continue

                geom = el.get("geometry")
                if geom:
                    best = None
                    for i in range(len(geom) - 1):
                        d = seg_dist_m(lat, lon, geom[i]["lat"], geom[i]["lon"], geom[i + 1]["lat"], geom[i + 1]["lon"])
                        if best is None or d < best:
                            best = d
                    if best is not None and best <= ROAD_RADIUS_M and (road_d is None or best < road_d):
                        o_road = name
                        road_d = best
                    continue

                e_lat = el.get("lat")
                e_lon = el.get("lon")
                if e_lat is None:
                    cen = el.get("center") or {}
                    e_lat = cen.get("lat")
                    e_lon = cen.get("lon")
                if e_lat is None or e_lon is None:
                    continue
                d = dist_m(lat, lon, float(e_lat), float(e_lon))

                if tags.get("place") in PLACE_TYPES:
                    if loc_d is None or d < loc_d:
                        o_locality = name
                        loc_d = d
                    continue

                if d > LANDMARK_RADIUS_M:
                    continue
                score = d
                for k in ["highway", "amenity", "railway", "shop", "public_transport", "healthcare"]:
                    if tags.get(k) in MAJOR_TYPES:
                        score = d - MAJOR_BONUS_M
                        break
                if lm_score is None or score < lm_score:
                    o_landmark = name
                    lm_score = score

            if not locality:
                locality = o_locality
            if not used_google:
                landmark = o_landmark
                road = o_road
        except Exception:
            frappe.log_error("Lead OpenStreetMap lookup failed")

    try:
        data = frappe.make_get_request(
            "https://nominatim.openstreetmap.org/reverse",
            params={"format": "jsonv2", "lat": lat, "lon": lon, "zoom": 18, "addressdetails": 1, "accept-language": "en"},
            headers=UA,
        ) or {}
        result["address"] = data.get("display_name") or ""
        addr = data.get("address") or {}
        result["city"] = addr.get("city") or addr.get("town") or addr.get("village") or addr.get("county") or ""
        result["state"] = addr.get("state") or ""
        if not locality:
            for key in ["neighbourhood", "suburb", "quarter", "hamlet", "village", "town", "city", "municipality"]:
                if addr.get(key):
                    locality = addr.get(key)
                    break
    except Exception:
        frappe.log_error("Lead address lookup failed")

    place = ""
    main = ""
    if landmark:
        main = pretty(landmark)
    elif road:
        main = pretty(road)
    if main:
        place = main
        if SHOW_LOCALITY_WITH_LANDMARK and locality and locality.lower() not in main.lower():
            place = main + ", " + locality
    elif locality:
        place = locality

    result["place"] = place[:140]
    result["landmark"] = pretty(landmark) if landmark else ""
    result["road"] = pretty(road) if road else ""
    result["locality"] = locality or ""
    result["source"] = source

frappe.response["message"] = result

# Returns the Lead details so any linked document can auto-fill them.
# Finds the Lead from (in order): lead -> quotation -> customer (Customer.lead_name).
# Also returns:
#   employee - Lead's Assigned Employee, else the Employee whose User is assigned
#              to the Lead (Assign To) or is the Lead Owner
#   customer - the Customer this Lead was converted into (Customer.lead_name)
# Args (all optional): lead, customer, quotation

LEAD_FIELDS = [
    "name", "lead_name", "first_name", "email_id", "phone", "mobile_no", "whatsapp_no",
    "custom_kseb_phone_number", "custom_consumer_no", "custom_current_bill",
    "custom_current_bill_image", "custom_kilo_watt__kw_", "custom_balance_feasibility",
    "custom_latitude", "custom_longitude", "custom_location_name", "custom_address",
    "city", "state", "country", "company", "custom_assigned_employee", "lead_owner", "_assign",
]

lead = frappe.form_dict.get("lead") or None
customer = frappe.form_dict.get("customer") or None
quotation = frappe.form_dict.get("quotation") or None

if not lead and quotation:
    q = frappe.db.get_value("Quotation", quotation, ["quotation_to", "party_name"], as_dict=True)
    if q:
        if q.quotation_to == "Lead":
            lead = q.party_name
        elif q.quotation_to == "Customer" and not customer:
            customer = q.party_name

if not lead and customer:
    lead = frappe.db.get_value("Customer", customer, "lead_name")

result = {}
if lead and frappe.db.exists("Lead", lead):
    d = frappe.db.get_value("Lead", lead, LEAD_FIELDS, as_dict=True) or {}
    for k in LEAD_FIELDS:
        if k != "_assign":
            result[k] = d.get(k)
    result["lead"] = lead

    # Employee: explicit field first, then Assign To users, then Lead Owner
    emp = d.get("custom_assigned_employee")
    if not emp:
        users = []
        try:
            users = json.loads(d.get("_assign") or "[]") or []
        except Exception:
            users = []
        if d.get("lead_owner"):
            users.append(d.get("lead_owner"))
        for u in users:
            emp = frappe.db.get_value("Employee", {"user_id": u, "status": "Active"}, "name")
            if emp:
                break
    result["employee"] = emp or None

    # Customer created from this Lead (if converted)
    cust = customer or frappe.db.get_value("Customer", {"lead_name": lead}, "name")
    result["customer"] = cust or None

frappe.response["message"] = result

# Site Visit: either Lead or Customer is required; keep them linked,
# and fill any blank details from the Lead.
lead = doc.get("custom_lead")

# Lead from Quotation (when created from a Lead quotation)
if not lead and doc.get("quotation"):
    q = frappe.db.get_value("Quotation", doc.quotation, ["quotation_to", "party_name", "custom_lead"], as_dict=True)
    if q:
        if q.quotation_to == "Lead":
            lead = q.party_name
        elif q.custom_lead:
            lead = q.custom_lead

# Lead from Customer
if not lead and doc.customer:
    lead = frappe.db.get_value("Customer", doc.customer, "lead_name")

if lead and not doc.get("custom_lead"):
    doc.custom_lead = lead

# Customer from Lead (once the Lead has been converted)
if lead and not doc.customer:
    cust = frappe.db.get_value("Customer", {"lead_name": lead}, "name")
    if cust:
        doc.customer = cust

if not doc.customer and not doc.get("custom_lead"):
    frappe.throw("Please select either a Lead or a Customer.")

# Fill blank details from the Lead
if lead and frappe.db.exists("Lead", lead):
    d = frappe.db.get_value("Lead", lead, [
        "lead_name", "mobile_no", "phone", "custom_address", "city", "state", "company",
        "custom_assigned_employee", "custom_latitude", "custom_longitude", "custom_location_name",
    ], as_dict=True) or {}
    addr = d.get("custom_address") or ", ".join([x for x in [d.get("city"), d.get("state")] if x])
    pairs = [
        ["employee", d.get("custom_assigned_employee")],
        ["contact_person", d.get("lead_name")],
        ["phone", d.get("mobile_no") or d.get("phone")],
        ["location_site_address", addr],
        ["company", d.get("company")],
        ["custom_latitude", d.get("custom_latitude")],
        ["custom_longitude", d.get("custom_longitude")],
        ["custom_location_name", d.get("custom_location_name")],
    ]
    for p in pairs:
        if p[1] and not doc.get(p[0]):
            doc.set(p[0], p[1])

# When a Customer is created from (or linked to) a Lead, fill this Customer into
# the documents that were started from that Lead before the Customer existed.
lead = doc.get("lead_name")
if lead:
    updated = 0

    # Site Visits / Solar Loans created directly from this Lead
    for sv in frappe.get_all("Site Visit", filters={"custom_lead": lead, "customer": ["is", "not set"]}, pluck="name"):
        frappe.db.set_value("Site Visit", sv, "customer", doc.name)
        updated += 1
    for ln in frappe.get_all("Solar Loan", filters={"custom_lead": lead, "customer": ["is", "not set"]}, pluck="name"):
        frappe.db.set_value("Solar Loan", ln, {"customer": doc.name, "customer_name": doc.customer_name})
        updated += 1

    # Site Visits / Solar Loans created from this Lead's Quotations
    quotations = frappe.get_all("Quotation", filters={"quotation_to": "Lead", "party_name": lead}, pluck="name")
    if quotations:
        for sv in frappe.get_all("Site Visit", filters={"quotation": ["in", quotations], "customer": ["is", "not set"]}, pluck="name"):
            frappe.db.set_value("Site Visit", sv, {"customer": doc.name, "custom_lead": lead})
            updated += 1
        for ln in frappe.get_all("Solar Loan", filters={"quotation": ["in", quotations], "customer": ["is", "not set"]}, pluck="name"):
            frappe.db.set_value("Solar Loan", ln, {"customer": doc.name, "customer_name": doc.customer_name, "custom_lead": lead})
            updated += 1

    # Paper Work for this Customer that has no Lead yet
    for pw in frappe.get_all("Paper Work", filters={"customer": doc.name, "custom_lead": ["is", "not set"]}, pluck="name"):
        frappe.db.set_value("Paper Work", pw, "custom_lead", lead)

    if updated:
        frappe.msgprint(str(updated) + " document(s) started from Lead " + lead + " are now linked to this Customer.", alert=True, indicator="green")

# Keep Quotation.custom_lead filled so the Lead Work Stage can track it.
if not doc.get("custom_lead") and doc.party_name:
    if doc.quotation_to == "Lead":
        doc.custom_lead = doc.party_name
    elif doc.quotation_to == "Customer":
        lead = frappe.db.get_value("Customer", doc.party_name, "lead_name")
        if lead:
            doc.custom_lead = lead

# Solar Loan: either Lead or Customer is required; keep them linked,
# and fill any blank contact details from the Lead.
lead = doc.get("custom_lead")

if not lead and doc.get("quotation"):
    q = frappe.db.get_value("Quotation", doc.quotation, ["quotation_to", "party_name", "custom_lead"], as_dict=True)
    if q:
        if q.quotation_to == "Lead":
            lead = q.party_name
        elif q.custom_lead:
            lead = q.custom_lead

if not lead and doc.customer:
    lead = frappe.db.get_value("Customer", doc.customer, "lead_name")

if lead and not doc.get("custom_lead"):
    doc.custom_lead = lead

if lead and not doc.customer:
    cust = frappe.db.get_value("Customer", {"lead_name": lead}, ["name", "customer_name"], as_dict=True)
    if cust:
        doc.customer = cust.name
        if not doc.get("customer_name"):
            doc.customer_name = cust.customer_name

if not doc.customer and not doc.get("custom_lead"):
    frappe.throw("Please select either a Lead or a Customer.")

if lead and frappe.db.exists("Lead", lead):
    d = frappe.db.get_value("Lead", lead, [
        "lead_name", "mobile_no", "phone", "email_id", "custom_address", "city", "state", "company",
    ], as_dict=True) or {}
    addr = d.get("custom_address") or ", ".join([x for x in [d.get("city"), d.get("state")] if x])
    pairs = [
        ["customer_name", d.get("lead_name")],
        ["contact_no", d.get("mobile_no") or d.get("phone")],
        ["email", d.get("email_id")],
        ["address", addr],
        ["company", d.get("company")],
    ]
    for p in pairs:
        if p[1] and not doc.get(p[0]):
            doc.set(p[0], p[1])

# Installation: fill blank contact, address and location from the Customer's Lead.
lead = None
if doc.customer:
    lead = frappe.db.get_value("Customer", doc.customer, "lead_name")

if lead and frappe.db.exists("Lead", lead):
    d = frappe.db.get_value("Lead", lead, [
        "lead_name", "mobile_no", "phone", "custom_address", "city", "state",
        "custom_latitude", "custom_longitude", "custom_location_name",
