# Applies Solar Settings > Forms, Work Stages and Names every time Solar Settings is saved.
#   Forms       -> field show / required / label changes and default print formats (Property Setters)
#   Work Stages -> gives every stage a key; the Customer Work Stage dashboard reads them
#   Names       -> words shown differently on this site (Translations)
# Switching a change off puts the original back. Running it again (e.g. after an app update)
# re-applies anything the update reset.
#
# The original value is never guessed from the current screen: a Property Setter made here keeps
# the original in its own "default_value" (marked "[solar-settings] "), and a Translation made here is marked with
# contribution_docname "solar-settings". So even if a save stops halfway, the next save still
# knows what the original was. Everything is checked first; nothing is written until all rows pass.
cint = frappe.utils.cint
MARK = "solar-settings"

state = json.loads(doc.get("custom_applied_state") or "{}") or {}
prev_ps = state.get("ps") or {}
prev_tr = state.get("tr") or {}
skipped = []


def as_text(v):
    if v is None:
        return ""
    return str(v)


def original(name, prev_ps, meta_value):
    # what this property was before Solar Settings touched it
    if name in prev_ps:
        return prev_ps[name]
    if frappe.db.exists("Property Setter", name):
        dv = frappe.db.get_value("Property Setter", name, "default_value") or ""
        if str(dv).startswith("[solar-settings] "):
            # made by Solar Settings earlier: the original is kept in it; reverting removes it
            return {"existed": 0, "orig": str(dv)[len("[solar-settings] "):]}
        pv = frappe.db.get_value("Property Setter", name, "value")
        return {"existed": 1, "orig": "" if pv is None else str(pv)}
    return {"existed": 0, "orig": "" if meta_value is None else str(meta_value)}


# ======================= 1. CHECK EVERYTHING (no changes yet) =======================

# ---- Work Stages ----
keys = []
for r in doc.get("custom_work_stages") or []:
    r.title = (r.title or "").strip()
    if not r.title:
        frappe.throw("Work Stages row " + str(r.idx) + ": enter a Stage Name")
    if not r.document or not frappe.db.exists("DocType", r.document):
        frappe.throw("Work Stages row " + str(r.idx) + " (" + r.title + "): choose a Document that exists on this site")
    if not r.key:
        base = "custom_"
        for ch in r.document.lower():
            if ch.isalnum() and ch.isascii():
                base = base + ch
            elif base[-1] != "_":
                base = base + "_"
        k = base.strip("_")
        i = 2
        while k in keys:
            k = base.strip("_") + "_" + str(i)
            i = i + 1
        r.key = k
    keys.append(r.key)
    if r.key.startswith("custom_"):
        meta = frappe.get_meta(r.document)
        cf = r.customer_field or "customer"
        if not meta.has_field(cf):
