# Server Script (API) - method: hipersign_solar_inventory
# Stock on hand per item and warehouse for the Solar "Inventory" page (same as the Fit Out Inventory view).
# Items are grouped into Low / Enough / Plenty in the browser. Reads use frappe.get_list (respects permissions).
bins = frappe.get_list("Bin", fields=["item_code", "warehouse", "actual_qty", "reserved_qty", "ordered_qty", "stock_value"],
                       limit_page_length=50000)
codes = {}
for b in bins:
    codes[b.item_code] = 1
code_list = list(codes.keys())

imeta = frappe.get_meta("Item")
ifields = ["name", "item_name", "item_group", "image", "stock_uom", "safety_stock", "modified"]
has_levels = 0
for f in ["fo_low_stock_level", "fo_plenty_stock_level"]:
    if imeta.has_field(f):
        ifields.append(f)
        has_levels = 1
items = {}
i = 0
while i < len(code_list):
    chunk = code_list[i:i + 500]
