                         "uom": r.stock_uom or "", "safety": float(r.safety_stock or 0), "levels": {}, "stock": [], "mod": str(r.modified or ""),
                         "low": float(r.get("fo_low_stock_level") or 0), "plenty": float(r.get("fo_plenty_stock_level") or 0)}

try:
    reorders = frappe.get_list("Item Reorder", filters={"parent": ["in", list(items.keys())]} if items else {"parent": "__none__"},
                               fields=["parent", "warehouse", "warehouse_reorder_level"], parent_doctype="Item", limit_page_length=50000)
except Exception:
    reorders = []
for r in reorders:
    if r.parent in items and r.warehouse:
        items[r.parent]["levels"][r.warehouse] = float(r.warehouse_reorder_level or 0)

used_wh = {}
for b in bins:
    it = items.get(b.item_code)
    if not it:
        continue
    it["stock"].append([b.warehouse, float(b.actual_qty or 0), float(b.reserved_qty or 0), float(b.ordered_qty or 0), float(b.stock_value or 0)])
    used_wh[b.warehouse] = 1

whs = []
if used_wh:
    for w in frappe.get_list("Warehouse", filters={"name": ["in", list(used_wh.keys())]}, fields=["name", "warehouse_name", "company"],
