glist.sort()

frappe.response["message"] = {"items": out, "warehouses": whs, "groups": glist, "default_level": 10, "plenty_factor": 3, "has_levels": has_levels}

# Solar - Customer Payment Request API  (api_method: solar_payment_request)
# mode=summary  customers=["A","B",...]  -> payment totals + WhatsApp number per customer (dashboard cards),
#                                           plus "_meta" (company name/phone, prepared by) for the WhatsApp message
# mode=detail   customer="A"             -> totals + customer, project, items, work stages,
#                                           payments, company (payment request letter)
#
# Total Amount     = submitted Sales Orders (not Closed)
#                  + submitted Sales Invoices not made from those orders
#                  + credit notes (negative)
# Amount Paid      = Payment Entries received (minus refunds paid back)
#                  + Journal / Bank / Cash entries crediting the customer
#                  + POS invoice payments
#   Each receipt is counted once, from the receipt itself, so a payment allocated first to the
#   order and later to the invoice is never counted twice.
# Remaining        = Total - Paid (never below 0; any excess is shown as credit)
# Outstanding      = invoiced so far - Paid (never below 0, never above Remaining)
# Note: Server Scripts run in RestrictedPython, which forbids x[k] += v, so totals use x[k] = x[k] + v.
flt = frappe.utils.flt
fd = frappe.form_dict
mode = fd.get("mode") or "detail"


def doc_value(r):
    if flt(r.get("base_rounded_total")) and not r.get("disable_rounded_total"):
        return flt(r.get("base_rounded_total"))
    return flt(r.get("base_grand_total"))


def add(d, key, v):
    d[key] = d[key] + v


def compute(cs):
    res = {}
    for c in cs:
        res[c] = {"customer": c, "order_total": 0.0, "extra_invoices": 0.0, "returns": 0.0,
                  "invoiced": 0.0, "paid": 0.0, "orders": 0, "invoices": 0, "receipts": 0}
    out = {"totals": res, "orders": [], "invoices": [], "payments": []}
    if not cs:
        return out

    sos = frappe.get_all("Sales Order",
        filters={"customer": ["in", cs], "docstatus": 1},
        fields=["name", "customer", "status", "transaction_date", "delivery_date", "project", "company",
                "base_grand_total", "base_rounded_total", "disable_rounded_total"],
        order_by="transaction_date asc, creation asc", limit_page_length=0)
    open_names = []
    for so in sos:
        so["value"] = doc_value(so)
        if so.status != "Closed":
            add(res[so.customer], "order_total", so["value"])
            add(res[so.customer], "orders", 1)
            open_names.append(so.name)
    out["orders"] = sos

    sis = frappe.get_all("Sales Invoice",
        filters={"customer": ["in", cs], "docstatus": 1},
        fields=["name", "customer", "posting_date", "due_date", "status", "is_return", "is_pos",
                "base_grand_total", "base_rounded_total", "disable_rounded_total", "outstanding_amount",
                "base_paid_amount", "base_change_amount"],
        order_by="posting_date asc, creation asc", limit_page_length=0)
    linked = {}
    if sis and open_names:
        rows = frappe.get_all("Sales Invoice Item",
            filters={"parent": ["in", [s.name for s in sis]], "sales_order": ["in", open_names]},
            fields=["parent", "sales_order"], limit_page_length=0)
        for it in rows:
            linked[it.parent] = it.sales_order
    pays = []
    for s in sis:
        v = doc_value(s)
        s["value"] = v
        s["sales_order"] = linked.get(s.name) or ""
        r = res[s.customer]
        add(r, "invoiced", v)
        add(r, "invoices", 1)
        if s.is_return:
            add(r, "returns", v)
        elif not s["sales_order"]:
            add(r, "extra_invoices", v)
        if s.is_pos:
            amt = flt(s.base_paid_amount) - flt(s.base_change_amount)
            if amt:
                pays.append({"customer": s.customer, "doctype": "Sales Invoice", "name": s.name,
                             "date": s.posting_date, "mode": "POS", "reference": "",
                             "amount": amt, "kind": "Payment" if amt > 0 else "Refund"})
    out["invoices"] = sis

    pes = frappe.get_all("Payment Entry",
        filters={"party_type": "Customer", "party": ["in", cs], "docstatus": 1,
                 "payment_type": ["in", ["Receive", "Pay"]]},
        fields=["name", "party", "payment_type", "posting_date", "mode_of_payment", "reference_no",
                "base_paid_amount"],
        order_by="posting_date asc, creation asc", limit_page_length=0)
    for p in pes:
        amt = flt(p.base_paid_amount)
        if p.payment_type == "Pay":
            amt = -amt
        pays.append({"customer": p.party, "doctype": "Payment Entry", "name": p.name,
                     "date": p.posting_date, "mode": p.mode_of_payment or "", "reference": p.reference_no or "",
                     "amount": amt, "kind": "Payment" if amt > 0 else "Refund"})

    jes = frappe.db.sql("""
        select a.party, j.name, j.posting_date, j.voucher_type, j.cheque_no,
               sum(a.credit - a.debit) as amt
        from `tabJournal Entry Account` a
        inner join `tabJournal Entry` j on j.name = a.parent
        where j.docstatus = 1 and a.party_type = 'Customer' and a.party in %(cs)s
          and j.voucher_type in ('Journal Entry', 'Bank Entry', 'Cash Entry')
        group by a.party, j.name, j.posting_date, j.voucher_type, j.cheque_no
    """, {"cs": tuple(cs)}, as_dict=True)
    for j in jes:
        amt = flt(j.amt)
        if amt:
            mode_label = "Bank" if j.voucher_type == "Bank Entry" else ("Cash" if j.voucher_type == "Cash Entry" else "Adjustment")
            pays.append({"customer": j.party, "doctype": "Journal Entry", "name": j.name,
                         "date": j.posting_date, "mode": mode_label, "reference": j.cheque_no or "",
                         "amount": amt, "kind": "Payment" if amt > 0 else "Refund"})

    for p in pays:
        add(res[p["customer"]], "paid", p["amount"])
        add(res[p["customer"]], "receipts", 1)
    out["payments"] = sorted(pays, key=lambda x: str(x["date"]))

    for c in cs:
        r = res[c]
        total = flt(r["order_total"] + r["extra_invoices"] + r["returns"], 2)
        if total < 0:
            total = 0
        paid = flt(r["paid"], 2)
        remaining = flt(total - paid, 2)
        if remaining < 0.5:
            remaining = 0
        credit = flt(paid - total, 2)
        if credit < 0.5:
            credit = 0
        invoiced = flt(r["invoiced"], 2)
        due = flt(invoiced - paid, 2)
        if due < 0.5:
            due = 0
        if due > remaining:
            due = remaining
        pct = 0
        if total > 0:
            pct = flt(min(100, paid * 100.0 / total), 1)
        if total <= 0 and paid <= 0:
            status = "No Orders"
        elif remaining <= 0:
            status = "Fully Paid"
        elif paid <= 0:
            status = "Unpaid"
        else:
            status = "Partly Paid"
        r["total"] = total
        r["paid"] = paid
        r["remaining"] = remaining
        r["outstanding"] = due
        r["invoiced"] = invoiced
        r["credit"] = credit
        r["percent"] = pct
        r["status"] = status
    return out


def permitted(names):
    if not names:
        return []
    return frappe.get_list("Customer", filters={"name": ["in", names]}, pluck="name", limit_page_length=0)


def addr_text(name):
    if not name:
        return ""
    a = frappe.db.get_value("Address", name, ["address_line1", "address_line2", "city", "state", "pincode"], as_dict=True)
    if not a:
        return ""
    parts = []
    for k in ["address_line1", "address_line2", "city"]:
        if a.get(k):
            parts.append(a.get(k))
    tail = " ".join([x for x in [a.get("state") or "", a.get("pincode") or ""] if x])
    if tail:
        parts.append(tail)
    return ", ".join(parts)


def latest(dt, filters, fields):
    try:
        f = {"docstatus": ["!=", 2]}
        for k in filters:
            f[k] = filters[k]
        rows = frappe.get_all(dt, filters=f, fields=["name", "creation", "modified"] + fields,
                              order_by="creation desc", limit_page_length=1)
        if rows:
            return rows[0]
    except Exception:
        pass
    return None


# WhatsApp number per customer, same order as the detail view:
# Lead WhatsApp No. > Customer Mobile > Contact Mobile/Phone > Lead Mobile/Phone (batched queries)
def phones_for(cs):
    out = {}
    if not cs:
        return out
    rows = frappe.get_all("Customer", filters={"name": ["in", cs]},
        fields=["name", "mobile_no", "lead_name", "customer_primary_contact"], limit_page_length=0)
    leads = [r.lead_name for r in rows if r.lead_name]
    lead_map = {}
    if leads:
        try:
            lrows = frappe.get_all("Lead", filters={"name": ["in", leads]}, fields=["name", "whatsapp_no", "mobile_no", "phone"], limit_page_length=0)
        except Exception:
            lrows = frappe.get_all("Lead", filters={"name": ["in", leads]}, fields=["name", "mobile_no", "phone"], limit_page_length=0)
        for l in lrows:
            lead_map[l.name] = l
    cons = [r.customer_primary_contact for r in rows if r.customer_primary_contact]
    con_map = {}
    if cons:
        for x in frappe.get_all("Contact", filters={"name": ["in", cons]}, fields=["name", "mobile_no", "phone"], limit_page_length=0):
            con_map[x.name] = x
    for r in rows:
        l = lead_map.get(r.lead_name) or {}
        x = con_map.get(r.customer_primary_contact) or {}
        out[r.name] = l.get("whatsapp_no") or r.mobile_no or x.get("mobile_no") or x.get("phone") or l.get("mobile_no") or l.get("phone") or ""
    return out


if mode == "summary":
    raw = fd.get("customers") or "[]"
    names = raw if isinstance(raw, list) else (json.loads(raw) or [])
    names = [n for n in names if n][:2500]
    allowed = permitted(names)
    data = compute(allowed)
    phones = phones_for(allowed)
    result = {}
    for c in allowed:
        t = data["totals"][c]
        result[c] = {"total": t["total"], "paid": t["paid"], "remaining": t["remaining"],
                     "outstanding": t["outstanding"], "credit": t["credit"], "percent": t["percent"],
                     "status": t["status"], "orders": t["orders"], "phone": phones.get(c) or ""}
    company = frappe.db.get_single_value("Global Defaults", "default_company")
    cd = {}
    if company:
        cd = frappe.db.get_value("Company", company, ["company_name", "phone_no"], as_dict=True) or {}
    result["_meta"] = {"company_name": cd.get("company_name") or company or "", "company_phone": cd.get("phone_no") or "",
                       "prepared_by": frappe.db.get_value("User", frappe.session.user, "full_name") or frappe.session.user,
                       "today": frappe.utils.nowdate()}
    frappe.response["message"] = result

else:
    c = fd.get("customer")
    if not c or not permitted([c]):
        frappe.throw("You do not have permission to view this customer.", title="Not permitted")

    data = compute([c])
    totals = data["totals"][c]

    cust = frappe.db.get_value("Customer", c,
        ["name", "customer_name", "mobile_no", "email_id", "customer_primary_address", "customer_primary_contact",
         "lead_name", "custom_site_address", "custom_location_name", "custom_consumer_no",
         "custom_kilo_watt__kw_", "gstin"], as_dict=True)

    phones = []
    emails = []

    def add_phone(num, src):
        if num and str(num).strip():
            n = str(num).strip()
            for p in phones:
                if p["number"] == n:
                    return
            phones.append({"number": n, "source": src})

    def add_email(e, src):
        if e and "@" in str(e):
            e = str(e).strip()
            for x in emails:
                if x["email"] == e:
                    return
            emails.append({"email": e, "source": src})

    lead = None
    if cust.lead_name:
        try:
            lead = frappe.db.get_value("Lead", cust.lead_name, ["whatsapp_no", "mobile_no", "phone", "email_id"], as_dict=True)
        except Exception:
            lead = frappe.db.get_value("Lead", cust.lead_name, ["mobile_no", "phone", "email_id"], as_dict=True)
    contact = None
    if cust.customer_primary_contact:
        contact = frappe.db.get_value("Contact", cust.customer_primary_contact, ["mobile_no", "phone", "email_id"], as_dict=True)

    sv = latest("Site Visit", {"customer": c}, ["status", "phone", "custom_location_name", "location_site_address", "property_type"])

    if lead and lead.get("whatsapp_no"):
        add_phone(lead.get("whatsapp_no"), "Lead WhatsApp No.")
    add_phone(cust.mobile_no, "Customer Mobile No.")
    if contact:
        add_phone(contact.mobile_no, "Contact Mobile")
        add_phone(contact.phone, "Contact Phone")
    if sv:
        add_phone(sv.get("phone"), "Site Visit Phone")
    if lead:
        add_phone(lead.get("mobile_no"), "Lead Mobile No.")
        add_phone(lead.get("phone"), "Lead Phone")

    add_email(cust.email_id, "Customer Email")
    if contact:
        add_email(contact.email_id, "Contact Email")
    if lead:
        add_email(lead.get("email_id"), "Lead Email")

    address = addr_text(cust.customer_primary_address)
    if not address:
        dl = frappe.get_all("Dynamic Link", filters={"link_doctype": "Customer", "link_name": c, "parenttype": "Address"}, pluck="parent", limit_page_length=1)
        if dl:
            address = addr_text(dl[0])
    location = cust.custom_location_name or (sv.get("custom_location_name") if sv else "") or ""
    site_address = cust.custom_site_address or (sv.get("location_site_address") if sv else "") or ""
    if not address:
        address = site_address

    # ---- work stages ----
    STAGES = [
        {"title": "Site Visit", "doctype": "Site Visit", "field": "customer", "status": "status", "done": ["Approved"]},
        {"title": "Quotation", "doctype": "Quotation", "field": "party_name", "status": "status", "done": ["Ordered", "Partially Ordered"], "extra": {"quotation_to": "Customer"}},
        {"title": "Loan", "doctype": "Solar Loan", "field": "customer", "status": "status", "done": ["Approved"], "optional": 1},
        {"title": "Sales Order", "doctype": "Sales Order", "field": "customer", "status": "status", "done": [], "submitted": 1},
        {"title": "Project", "doctype": "Project", "field": "customer", "status": "status", "done": ["Completed"]},
        {"title": "Product Delivery", "doctype": "Product Delivery", "field": "customer", "status": "transfer_status", "done": ["Transferred"]},
        {"title": "Installation", "doctype": "Installation", "field": "customer", "status": "installation_status", "done": ["Completed"]},
        {"title": "Paper Work", "doctype": "Paper Work", "field": "customer", "status": "status", "done": ["Completed"]},
        {"title": "KSEB Paperwork", "doctype": "KSEB Paper Works", "field": "customer", "status": "status_of_kseb_paper_work", "done": ["Completed"]},
        {"title": "Subsidy", "doctype": "Subsidy", "field": "customer", "status": "status", "done": ["Sanctioned"]},
        {"title": "Project Commission", "doctype": "Project Commission", "field": "customer", "status": "status_of_project_commission", "done": ["Commissioned"]},
        {"title": "Sales Invoice", "doctype": "Sales Invoice", "field": "customer", "status": "status", "done": ["Paid"]},
    ]
    stages = []
    has_order = totals["orders"] > 0
    current = None
    capacity = cust.custom_kilo_watt__kw_ or ""
    for st in STAGES:
        filters = {st["field"]: c}
        for k in (st.get("extra") or {}):
            filters[k] = st["extra"][k]
        extra_fields = [st["status"], "docstatus"]
        if st["doctype"] in ("KSEB Paper Works", "Subsidy"):
            extra_fields.append("capacity_kw")
        rec = latest(st["doctype"], filters, extra_fields)
        row = {"title": st["title"], "doctype": st["doctype"], "name": "", "status": "", "state": "pend", "date": None}
        if rec:
            status = rec.get(st["status"]) or ""
            if st.get("submitted"):
                done = rec.get("docstatus") == 1
                if done:
                    status = "Confirmed"
            else:
                done = str(status).strip().lower() in [x.lower() for x in st["done"]]
            row["name"] = rec.name
            row["status"] = status or "In Progress"
            row["state"] = "done" if done else "prog"
            row["date"] = rec.modified
            if not capacity and rec.get("capacity_kw"):
                capacity = str(rec.get("capacity_kw")) + " kW"
            if current is None or str(rec.modified) > str(current["date"]):
                current = row
        elif st.get("optional") and has_order:
            row["state"] = "na"
            row["status"] = "Not Required"
        stages.append(row)

    # ---- orders, items, projects ----
    orders = []
    company = None
    for so in data["orders"]:
        if so.status == "Closed":
            continue
        if not company:
            company = so.company
        items = frappe.get_all("Sales Order Item", filters={"parent": so.name},
            fields=["item_code", "item_name", "qty", "uom", "base_amount", "idx"],
            order_by="idx asc", limit_page_length=0)
        proj = None
        if so.project:
            proj = frappe.db.get_value("Project", so.project, ["name", "project_name", "status", "percent_complete", "expected_end_date"], as_dict=True)
        orders.append({"name": so.name, "date": so.transaction_date, "delivery_date": so.delivery_date,
                       "status": so.status, "value": so["value"], "project": proj,
                       "items": [{"item_code": i.item_code, "item_name": i.item_name, "qty": flt(i.qty),
                                  "uom": i.uom, "amount": flt(i.base_amount)} for i in items]})

    invoices = [{"name": s.name, "date": s.posting_date, "due_date": s.due_date, "status": s.status,
                 "value": s["value"], "outstanding": flt(s.outstanding_amount), "is_return": s.is_return,
                 "sales_order": s["sales_order"]} for s in data["invoices"]]

    # ---- company ----
    if not company:
        company = frappe.db.get_single_value("Global Defaults", "default_company")
    comp = {}
    if company:
        cd = frappe.db.get_value("Company", company, ["company_name", "phone_no", "email", "website", "company_logo", "gstin"], as_dict=True) or {}
        caddr = ""
        links = frappe.get_all("Dynamic Link", filters={"link_doctype": "Company", "link_name": company, "parenttype": "Address"}, pluck="parent", limit_page_length=5)
        for a in links:
            caddr = addr_text(a)
            if caddr:
                break
        bank = []
        try:
            bank = frappe.get_all("Bank Account", filters={"company": company, "is_company_account": 1, "disabled": 0},
                fields=["account_name", "bank", "bank_account_no", "branch_code"],
                order_by="is_default desc, creation asc", limit_page_length=1)
        except Exception:
            bank = []
        comp = {"name": company, "company_name": cd.get("company_name") or company, "phone": cd.get("phone_no") or "",
                "email": cd.get("email") or "", "website": cd.get("website") or "", "logo": cd.get("company_logo") or "",
                "gstin": cd.get("gstin") or "", "address": caddr, "bank": bank[0] if bank else None}

    user_name = frappe.db.get_value("User", frappe.session.user, "full_name") or frappe.session.user

    frappe.response["message"] = {
        "customer": {"name": cust.name, "customer_name": cust.customer_name or cust.name, "address": address,
                     "site_address": site_address, "location": location, "consumer_no": cust.custom_consumer_no or "",
                     "capacity": capacity, "gstin": cust.gstin or "", "property_type": (sv.get("property_type") if sv else "") or "",
                     "phones": phones, "emails": emails},
        "totals": totals,
        "orders": orders,
        "invoices": invoices,
        "payments": [p for p in data["payments"]],
        "stages": stages,
        "current_stage": current,
        "company": comp,
        "prepared_by": user_name,
        "today": frappe.utils.nowdate(),
    }
